-- «Batafsil» matnlari — Kanishka, Muqanna, Ismoil Somoniy va Narshaxiy.

-- ================================= KANISHKA =================================

UPDATE fact_cards SET detail_uz = $$Men Kushon podsholigining hukmdoriman; saltanatim eng yuksak cho'qqiga aynan mening davrimda chiqqan.

Mening hayotim haqidagi ma'lumotlar tosh bitiklar, tangalar va buddaviy manbalarga tayanadi — hukmronligimning aniq yillari haqida olimlar orasida turli qarashlar mavjud. Kushon davlati hozirgi O'zbekiston janubi, Afg'oniston, Pokiston va Shimoliy Hindiston hududlarini qamrab olgan ulkan saltanat edi.$$
 WHERE topic_uz = $$Kimman?$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'kanishka');

UPDATE fact_cards SET detail_uz = $$Kushon davlati milodiy I asrdan III asrgacha hukm surgan.

