 WHERE topic_uz = $$Saltanat davri$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'kanishka');

UPDATE fact_cards SET detail_uz = $$Men poytaxtni Baqtriyadan Peshovar (qadimgi nomi Purushapura) shahriga ko'chirganman.

