 WHERE topic_uz = $$Poytaxt$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'kanishka');

UPDATE fact_cards SET detail_uz = $$Davlatim hududiga hozirgi Hindiston shimoli, Xo'tan, Afg'oniston va O'zbekiston janubidagi yerlar kirgan.

Bunday keng hududni boshqarish uchun yo'llar, pochta aloqasi va mahalliy hokimlar tizimi kerak edi. Turli o'lkada turli til va din bo'lgan, shuning uchun boshqaruvda murosa siyosati yuritilgan: mahalliy an'analarga aralashilmagan. Aynan shu siyosat saltanatning uzoq turishini ta'minlagan.$$
 WHERE topic_uz = $$Saltanat hududi$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'kanishka');

UPDATE fact_cards SET detail_uz = $$O'sha davrda dunyoda to'rtta yirik davlat mavjud edi: Rim, Parfiya, Xitoy va Kushon podsholigi.

Bu davlatlar bir-biri bilan savdo va elchilik aloqalarida bo'lgan; ular orasidagi yo'l Buyuk ipak yo'li deb ataladi. Kushon davlati bu yo'lning markaziy qismini nazorat qilgani uchun alohida ahamiyatga ega edi: Sharqdan G'arbga ketayotgan har bir karvon uning hududidan o'tardi. Bizning yurtimiz shu tariqa qadimgi dunyoning chorrahasida turgan.$$
 WHERE topic_uz = $$Buyuk davlatlar qatorida$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'kanishka');

UPDATE fact_cards SET detail_uz = $$Mening davrimda yangi shaharlar bunyod etilgan va Hindiston, Xitoy hamda Rim bilan aloqalar kengaygan.

Savdo karvonlari ipak, ziravor, qimmatbaho toshlar va shisha buyumlar tashigan. Savdo bilan birga g'oyalar ham ko'chgan: buddaviylik Hindistondan shimolga aynan shu yo'l orqali tarqalgan. Arxeologlar Termiz atrofidan Rim tangalari va Hindiston buyumlarini topgan — bu aloqalarning naqadar keng bo'lganini ko'rsatadi.$$
 WHERE topic_uz = $$Savdo va elchilik$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'kanishka');

