 WHERE topic_uz = $$Drama qahramoniman$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'muqanna');

-- ============================== ISMOIL SOMONIY ==============================

UPDATE fact_cards SET detail_uz = $$849-yilda Farg'onada tug'ilganman. Sulolamiz bobokalonimiz Somonxudot nomi bilan atalgan.

Somoniylar dastlab Movarounnahrning turli viloyatlarida hokim bo'lib xizmat qilgan: aka-ukalar Samarqand, Farg'ona, Shosh va Hirotni boshqargan. Bu oila asta-sekin kuchayib borgan va oxir-oqibat mustaqil davlat tuzgan. Mening vazifam shu tarqoq mulklarni yagona davlatga birlashtirish bo'ldi.$$
 WHERE topic_uz = $$Tug'ilishim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'ismoil-somoniy');

UPDATE fact_cards SET detail_uz = $$Avval Buxoro shahriga noib etib tayinlanganman, keyin butun davlatga hukmdor bo'lganman.

Buxoro o'sha paytda unchalik katta shahar emasdi, ammo men uni poytaxt qilib tanladim va rivojlantirdim. Boshqaruvni tartibga soldim: soliq miqdorini belgiladim, savdo yo'llarini xavfsizlantirdim, devon — boshqaruv idorasini tuzdim. Poytaxt tanlash uzoq muddatli qaror: u shaharning keyingi asrlardagi taqdirini belgilaydi.$$
 WHERE topic_uz = $$Buxoro noibi$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'ismoil-somoniy');

UPDATE fact_cards SET detail_uz = $$893-yilda Taroz shahriga harbiy yurish qilib, g'alaba bilan qaytganman.

Taroz (hozirgi Qozog'iston hududida) shimoliy chegaradagi muhim savdo shahri edi. Yurishning maqsadi chegarani mustahkamlash va savdo yo'lini himoya qilish bo'lgan. G'alabadan keyin shahar bosh cherkovi masjidga aylantirilgani manbalarda qayd etilgan. Bu yurish davlatimning shimoliy chegarasini belgilagan va keyingi yillarda savdo xavfsizligini ta'minlagan.$$
 WHERE topic_uz = $$Taroz yurishi$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'ismoil-somoniy');

UPDATE fact_cards SET detail_uz = $$Men butun Movarounnahrni birlashtirib, yagona kuchli davlat tuzganman.

Bundan avval bu yerlar turli hokimlar qo'lida edi va ular o'zaro nizolashardi. Birlashtirish osoyishtalik keltirgan: karvon yo'llari xavfsiz bo'lgan, savdo rivojlangan, soliq tartibga solingan. Yagona davlat ilm va madaniyat uchun ham qulay muhit yaratgan — Buxoro aynan shu davrda ilm markaziga aylangan. Tinchlik ravnaqning birinchi sharti ekanini tarix ko'p marta ko'rsatgan.$$
 WHERE topic_uz = $$Yagona davlat$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'ismoil-somoniy');

UPDATE fact_cards SET detail_uz = $$Xuroson uchun bo'lgan kurashda safforiylar ustidan g'alaba qozonganman.

Safforiylar — Eron sharqida hukmronlik qilgan sulola; ular Movarounnahrga ham da'vo qilgan. G'alabadan keyin Xuroson bizning davlatimiz tarkibiga kirgan va Somoniylar davlati mintaqadagi eng yirik kuchga aylangan. Bu g'alaba Bag'dod xalifasining e'tirofini ham keltirgan — u menga hukmronlik yorlig'ini yuborgan.$$
 WHERE topic_uz = $$Xuroson uchun kurash$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'ismoil-somoniy');

UPDATE fact_cards SET detail_uz = $$Zamondoshlarim meni dono va adolatli hukmdor deb bilishgan.

Manbalarda yozilishicha, men arz bilan kelgan odamlarni o'zim tinglaganman va amaldorlarning nohaqligini jazolaganman. Olim va shoirlarga homiylik qilganman, madrasa va kutubxonalar ishlashi uchun sharoit yaratganman. Hukmdorning adolati faqat axloqiy masala emas: adolatsiz boshqaruvda soliq yig'ilmaydi, savdo to'xtaydi va davlat zaiflashadi.$$
 WHERE topic_uz = $$Adolatli boshqaruv$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'ismoil-somoniy');

UPDATE fact_cards SET detail_uz = $$Keyingi avlodlar meni hurmat bilan «amiri moziy», ya'ni «o'tgan amir» deb atashgan.

