 WHERE topic_uz = $$«Amiri moziy» laqabim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'ismoil-somoniy');

UPDATE fact_cards SET detail_uz = $$Tarixchi Narshaxiy «Buxoro tarixi» asarida mening hukmronligim va davlat ishlarim haqida yozib qoldirgan.

