 WHERE topic_uz = $$Narshaxiy guvohligi$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'ismoil-somoniy');

UPDATE fact_cards SET detail_uz = $$907-yilda poytaxtim Buxoro shahrida vafot etganman.

