 WHERE topic_uz = $$Umrim oxiri$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'ismoil-somoniy');

UPDATE fact_cards SET detail_uz = $$Otam Ahmad ibn Asad Somoniylar xonadonining hukmdorlaridan edi; akalarim ham turli viloyatlarni boshqargan.

Oilada hokimiyat taqsimlanishi o'sha davr uchun odatiy hol edi, ammo u ko'pincha nizoga olib kelardi. Akam Nasr bilan o'rtamizda ham kelishmovchilik bo'lgan, keyinchalik esa hokimiyat menga o'tgan. Sulola ichidagi nizolar davlatni zaiflashtiradi — shuning uchun men birlashtirishni asosiy vazifa deb bilganman.$$
 WHERE topic_uz = $$Oilam$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'ismoil-somoniy');

UPDATE fact_cards SET detail_uz = $$Davlatimizning poytaxti Buxoro shahri bo'lgan va u mening davrimda tez o'sgan.

Shaharda madrasalar, masjidlar, kutubxonalar, bozorlar va karvonsaroylar qurilgan. Buxoro «Buxoroyi sharif» — «muborak Buxoro» nomi bilan mashhur bo'lgan. Bu yerdagi saroy kutubxonasi o'z davrining eng boy to'plamlaridan biri edi; keyinchalik yosh Ibn Sino aynan shu kutubxonada bilim olgan. Poytaxt shu tariqa butun mintaqaning ilmiy markaziga aylangan.$$
 WHERE topic_uz = $$Poytaxtim Buxoro$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'ismoil-somoniy');

UPDATE fact_cards SET detail_uz = $$Somoniylar davrida Buxoro ilm-fan va madaniyat markaziga aylangan.

