 WHERE topic_uz = $$Ilm-fan ravnaqi$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'ismoil-somoniy');

UPDATE fact_cards SET detail_uz = $$Davlatimizda kumush dirhamlar zarb etilgan va ular savdo karvonlari bilan juda uzoq o'lkalarga tarqalgan.

