 WHERE topic_uz = $$Tug'ilishim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'narshaxiy');

UPDATE fact_cards SET detail_uz = $$To'la ismim uzun: Abu Bakr Muhammad ibn Ja'far ibn Zakariyo ibn Xattob ibn Sharik an-Narshaxiy.

