 WHERE topic_uz = $$To'la ismim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'narshaxiy');

UPDATE fact_cards SET detail_uz = $$943–944-yillarda arab tilida «Buxoro tarixi» kitobini yozganman.

