 WHERE topic_uz = $$«Buxoro tarixi» kitobim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'narshaxiy');

UPDATE fact_cards SET detail_uz = $$Kitobimni somoniy hukmdor amir Nuh ibn Nasrga bag'ishlaganman.

