 WHERE topic_uz = $$Fors tiliga tarjima$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'narshaxiy');

UPDATE fact_cards SET detail_uz = $$1178–1179-yillarda Muhammad ibn Zufar forscha tarjimani yana bir bor qayta ishlagan.

