 WHERE topic_uz = $$Keyingi tahrir$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'narshaxiy');

UPDATE fact_cards SET detail_uz = $$Kitobim turli nomlar bilan mashhur bo'lgan: «Tarixi Narshaxiy», «Tarixi Buxoro» va boshqalar.

