 WHERE topic_uz = $$Kitobimning nomlari$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'narshaxiy');

UPDATE fact_cards SET detail_uz = $$Kitobim 1892-yilda Parijda nashr etilgan, 1897-yilda esa Toshkentda rus tilida chop etilgan.

Yevropa sharqshunoslari o'rta asr manbalarini izlab topib, nashr qilish bilan shug'ullangan — shu tufayli ko'plab qo'lyozma ilmiy muomalaga kirgan. Nashr etilgan kitob yo'qolmaydi: uning nusxalari ko'p kutubxonaga tarqaladi. Mening asarim shu tariqa jahon ilmiga tanish bo'lgan va u bugun Markaziy Osiyo tarixini o'rganishda asosiy manbalardan biri sanaladi.$$
 WHERE topic_uz = $$Jahon e'tirofi$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'narshaxiy');

